"""Revision-aware lease census and causal application service classification."""
from common import addresses
from ledger import group_records, reconcile
from protocols import signature


def _empty_service(service_id):
    return {'id': service_id,
            'internal_open': [], 'internal_closed': [],
            'external_open': [], 'external_closed': [],
            'internal_only': [], 'protocol_errors': 0}


def _status_for_group(group_rows, kind):
    """Return ('open', sig) / ('closed', None) / ('unknown', None), errors."""
    max_attempt = -1
    for _, record in group_rows:
        if record.attempt > max_attempt:
            max_attempt = record.attempt
    all_closed = True
    all_open = True
    signatures = []
    errors = 0
    for _, record in group_rows:
        if record.attempt != max_attempt:
            continue
        if record.result == 'closed':
            all_open = False
        elif record.result == 'timeout':
            all_closed = False
            all_open = False
        elif record.result == 'open':
            all_closed = False
            sig = signature(kind, record.payload)
            if sig is None:
                all_open = False
                errors += 1
            else:
                signatures.append(sig)
        else:
            # Should be impossible after record validation.
            all_closed = False
            all_open = False
    if all_closed:
        return 'closed', None, errors
    if all_open and signatures and all(sig == signatures[0] for sig in signatures):
        return 'open', signatures[0], errors
    return 'unknown', None, errors


def build(context, records, low):
    """Build all query snapshots and the frozen request-activity map."""
    groups = group_records(records)
    lease_ids = sorted(context['leases'])
    service_ids = sorted(context['services'])
    services_kind = context['services']
    leases = context['leases']

    # Per-query (internal address set, {service: (open set, closed set)}).
    info_by_query = {}
    snapshots = []

    for query in context['queries']:
        (live, deleted, conflict), live_icmp, live_app = reconcile(groups, query)

        icmp_by_lease = {lid: [] for lid in lease_ids}
        app_by_lease = {lid: [] for lid in lease_ids}
        for record in live_icmp:
            icmp_by_lease[record.lease].append(record)
        for record in live_app:
            app_by_lease[record.lease].append(record)

        unbound_total = 0
        lease_outputs = []
        query_info = {}

        for lease_id in lease_ids:
            lease = leases[lease_id]
            is_active = lease['start'] <= query < lease['end']

            internal = set()
            external = set()
            internal_witness = {}
            external_witness = {}
            conflicts = []

            if not is_active:
                state = 'inactive'
                unresolved = []
            else:
                alias = False
                for record in icmp_by_lease[lease_id]:
                    target = record.target
                    responder = record.responder
                    result = record.result
                    if record.canary:
                        if result == 'echo' and responder == target:
                            alias = True
                        # Other canary responses establish neither role.
                        continue
                    if result == 'echo' and responder == target:
                        previous = internal_witness.get(target)
                        if previous is None or record.event < previous:
                            internal_witness[target] = record.event
                    elif result != 'timeout' and responder != target:
                        previous = external_witness.get(responder)
                        if previous is None or record.event < previous:
                            external_witness[responder] = record.event
                    # A timeout, or a self error, establishes no role.

                internal = set(internal_witness)
                external = set(external_witness)
                conflicts = sorted(internal & external)
                if alias:
                    state = 'alias'
                elif conflicts:
                    state = 'conflict'
                else:
                    state = 'usable'

            if state == 'usable':
                unresolved = sorted(low[lease_id] - internal - external)
            elif state == 'inactive':
                unresolved = []
            else:
                unresolved = sorted(low[lease_id])
                internal = set()
                external = set()
                internal_witness = {}
                external_witness = {}

            # ---- application census -------------------------------------
            service_outputs = []
            if state != 'usable':
                unbound_total += len(app_by_lease[lease_id])
                for service_id in service_ids:
                    service_outputs.append(_empty_service(service_id))
                query_info[lease_id] = (set(), {})
            else:
                eligible = {}
                for record in app_by_lease[lease_id]:
                    target = record.target
                    if target in internal:
                        role = 1
                        witness = internal_witness.get(target)
                    elif target in external:
                        role = 2
                        witness = external_witness.get(target)
                    else:
                        unbound_total += 1
                        continue
                    if witness is None or witness > record.event:
                        unbound_total += 1
                        continue
                    by_target = eligible.get(record.service)
                    if by_target is None:
                        by_target = {}
                        eligible[record.service] = by_target
                    group_rows = by_target.get(target)
                    if group_rows is None:
                        by_target[target] = [(role, record)]
                    else:
                        group_rows.append((role, record))

                status_map = {}
                for service_id in service_ids:
                    groups_for_service = eligible.get(service_id)
                    internal_open = set()
                    internal_closed = set()
                    external_open = set()
                    external_closed = set()
                    protocol_errors = 0
                    if groups_for_service:
                        kind = services_kind[service_id]
                        for target, group_rows in groups_for_service.items():
                            status, _sig, errors = _status_for_group(group_rows, kind)
                            protocol_errors += errors
                            role = group_rows[0][0]
                            if status == 'open':
                                if role == 1:
                                    internal_open.add(target)
                                else:
                                    external_open.add(target)
                            elif status == 'closed':
                                if role == 1:
                                    internal_closed.add(target)
                                else:
                                    external_closed.add(target)
                    status_map[service_id] = (internal_open, internal_closed)
                    if external and external_closed == external:
                        internal_only = internal_open
                    else:
                        internal_only = set()
                    service_outputs.append({
                        'id': service_id,
                        'internal_open': addresses(internal_open),
                        'internal_closed': addresses(internal_closed),
                        'external_open': addresses(external_open),
                        'external_closed': addresses(external_closed),
                        'internal_only': addresses(internal_only),
                        'protocol_errors': protocol_errors,
                    })
                query_info[lease_id] = (internal, status_map)

            lease_outputs.append({
                'lease': lease_id,
                'state': state,
                'conflicts': addresses(conflicts),
                'internal': addresses(internal),
                'external': addresses(external),
                'unresolved': addresses(unresolved),
                'services': service_outputs,
            })

        info_by_query[query] = query_info
        snapshots.append({
            'at': query,
            'ledger': {'live': live, 'deleted': deleted, 'conflict': conflict},
            'unbound_applications': unbound_total,
            'leases': lease_outputs,
        })

    # Request activity is frozen at the request's own query.
    active_map = {}
    for request_id in sorted(context['requests']):
        request = context['requests'][request_id]
        query_info = info_by_query[request['at']]
        internal, status_map = query_info.get(request['lease'], (set(), {}))
        target = request['address']
        is_active = False
        if target in internal:
            open_set, closed_set = status_map.get(request['service'], (set(), set()))
            is_active = target not in open_set and target not in closed_set
        active_map[request_id] = is_active

    return snapshots, active_map
